  bool CanSend(){var r=runner();return r!=null&&ReferenceEquals(r,observed)&&r.State==RuntimeState.WaitingForInput&&Inspection!=null&&r.Generation==Inspection.Generation;}
  void SendInput(){if(!CanSend()||clock.ElapsedMilliseconds-lastSend<250)return;var before=runner();long visit=before.CurrentVisit;submit(Input.Text);if(ReferenceEquals(before,runner())&&(before.State!=RuntimeState.WaitingForInput||before.CurrentVisit!=visit))lastSend=clock.ElapsedMilliseconds;RefreshState();if(CanSend()){notice.Text=runner().LastMessage;Input.Focus();}}
  internal void FocusPendingInput(){if(inputArea.Visible)Input.Focus();}
  protected override void Dispose(bool disposing){if(disposing&&!closed){closed=true;if(watchWindow!=null&&!watchWindow.IsDisposed)watchWindow.Close();watchWindow=null;watchContext=null;watchInspection=null;Ui.ThemeChanged-=ThemeChanged;pulse.Stop();pulse.Dispose();session.Clear();Inspection=null;selected=null;Variables.Items.Clear();Detail.Clear();}base.Dispose(disposing);if(disposing)DisposeReadableFonts();}
 }
